-- Matrix unified notification platform - phase 2
-- MySQL 8.0+
CREATE TABLE IF NOT EXISTS im_user_sync_cursor (tenant_id VARCHAR(64) NOT NULL,user_id VARCHAR(128) NOT NULL,current_version BIGINT NOT NULL DEFAULT 0,updated_time DATETIME(3) NOT NULL,PRIMARY KEY (tenant_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户通知增量同步游标';
CREATE TABLE IF NOT EXISTS im_push_event (id VARCHAR(32) NOT NULL,event_id VARCHAR(64) NOT NULL,tenant_id VARCHAR(64) NOT NULL,user_id VARCHAR(128) NOT NULL,version BIGINT NOT NULL,event_type VARCHAR(64) NOT NULL,notification_id VARCHAR(32) NULL,payload_json JSON NOT NULL,status VARCHAR(32) NOT NULL,created_time DATETIME(3) NOT NULL,pushed_time DATETIME(3) NULL,PRIMARY KEY(id),UNIQUE KEY uk_im_push_event_id(event_id),UNIQUE KEY uk_im_push_user_version(tenant_id,user_id,version),KEY idx_im_push_user_created(tenant_id,user_id,created_time),KEY idx_im_push_notification(notification_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户实时推送及断线补拉事件';
CREATE TABLE IF NOT EXISTS im_delivery_receipt (id VARCHAR(32) NOT NULL,tenant_id VARCHAR(64) NOT NULL,notification_id VARCHAR(32) NOT NULL,user_id VARCHAR(128) NOT NULL,device_id VARCHAR(128) NOT NULL,client_type VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,delivered_time DATETIME(3) NULL,read_time DATETIME(3) NULL,created_time DATETIME(3) NOT NULL,updated_time DATETIME(3) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_im_receipt_device(notification_id,user_id,device_id),KEY idx_im_receipt_user_status(tenant_id,user_id,status,updated_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='通知设备送达与已读回执';
